import '../../assets/lri-motion-scene.js';
import {renderLessonSVG,lessonArithmetic} from './foundation-scenes.js?v=foundation-lessons-v5';
/* One instructional clock. Each instance owns its scene, controls and lifecycle. */
const CSS=`
:host{--lesson-scroll-offset:calc(120px + env(safe-area-inset-top,0px));display:block;scroll-margin-block-start:var(--lesson-scroll-offset);min-width:0;max-width:100%;margin:20px 0;color:#18314b;font:16px/1.55 Arial,"Microsoft YaHei",sans-serif}
header,h3,.steps,.scene,.controls,button,select{scroll-margin-block-start:var(--lesson-scroll-offset);scroll-margin-block-end:80px}
.lesson{border:1px solid #cbd8e6;border-radius:18px;background:#fff;overflow:hidden;box-shadow:0 5px 18px #18314b08}
header{padding:13px 20px 8px;background:#fff;scroll-margin-block-start:32px}.eyebrow{margin:0 0 5px;color:#64778b;font-size:13px;font-weight:700}h3{margin:0;font-size:22px;line-height:1.3}p{margin:10px 0}.narration{font-size:16px;line-height:1.75;margin:0;color:#334f67}
.content{padding:0 12px 16px}.scene{max-width:820px;margin:auto;border-radius:15px;overflow:hidden;background:#0c1b32}.caption{padding:15px 8px 0;display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:8px 20px}.caption .takeaway{grid-column:1/-1;margin:0;padding:9px 0 0;border-top:1px solid #e2e9f0}.progress{height:3px;margin:0 20px;background:#e6edf4;overflow:hidden}.progress span{display:block;height:100%;width:0;background:linear-gradient(90deg,#169a92,#3865a3)}.formula{margin:0;padding:10px 12px;background:#f4f7fb;border-left:3px solid #397b92;font:16px/1.5 ui-monospace,Consolas,monospace;overflow-wrap:anywhere}.takeaway{font-size:16px;color:#334f67;padding:0 3px}.citation{font-size:12px;vertical-align:super;color:#a9232b;margin-left:6px}
.controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:8px 20px;border-top:0;background:#fff}button,select{font:inherit;font-size:14px;min-height:42px;border:1px solid #b6c8d9;background:white;color:#19334d;border-radius:8px;padding:7px 12px;cursor:pointer}button[data-action=play]{background:#ac1d28;color:white;border-color:#ac1d28}button:disabled{opacity:.45;cursor:default}button:focus-visible,select:focus-visible{outline:3px solid #16889a;outline-offset:2px}.rate{margin-left:auto;display:flex;gap:6px;align-items:center;font-size:13px}.status{font-size:13px;color:#5d7184;margin:0;padding:0 20px 12px}.steps{display:flex;gap:7px;flex-wrap:wrap;padding:5px 20px 10px}.steps button{border-radius:50%;width:35px;min-height:35px;padding:0}.steps button[aria-current=step]{background:#17374f;color:#fff;border-color:#17374f}.current{font-weight:700}.fallback{padding:18px}.reduced{color:#5d7184}.scene lri-motion-scene{--lri-motion-scroll-offset:var(--lesson-scroll-offset)}
@media(min-width:760px){.toolbar{display:flex;align-items:center;gap:12px;padding:3px 16px 9px}.controls{flex:1;flex-wrap:nowrap;padding:0;gap:6px}.controls button,.controls select{padding-inline:8px;font-size:13px}.steps{padding:0;flex-wrap:nowrap;gap:5px}.rate{gap:4px}.rate span{font-size:12px}}
@media(max-width:520px){header{padding:12px 14px 7px}h3{font-size:20px}.content{padding:0 8px 12px}.caption{display:block;padding:12px 6px 0}.caption .formula{margin:10px 0}.progress{margin:0 14px}.narration{font-size:16px;min-height:0}.controls{padding:12px 10px;gap:6px}.rate{margin-left:0;grid-column:1/-1;flex-wrap:wrap}.controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));padding-right:72px}.controls button{min-width:0;padding-inline:5px;overflow-wrap:anywhere}.steps{display:grid;grid-template-columns:repeat(3,minmax(44px,1fr));gap:8px;padding:4px 72px 10px 14px}.steps button{border-radius:9px;width:100%;min-height:44px}.formula{font-size:15px}.status{padding:0 14px 12px}.scene{max-width:360px}}
@media print{.controls,.steps,.status{display:none}.lesson{break-inside:avoid}.narration{min-height:0}}
`;
export class LriFoundationLesson extends HTMLElement{
 #root;#data;#step=0;#elapsed=0;#playing=false;#rate=1;#last=0;#raf=0;#motion;#intersection;#resize;#visible=false;#abort;#scene;#narrow=false;#pending=0;#ui;#ready=false;#reason='paused';
 constructor(){super();this.#root=this.attachShadow({mode:'open'});this.#root.innerHTML='<style>'+CSS+'</style><section class="lesson"><header><p class="eyebrow"></p><h3></h3></header><div class="progress" aria-hidden="true"><span></span></div><div class="toolbar"><div class="controls"><button data-action="prev"></button><button data-action="play"></button><button data-action="next"></button><button data-action="restart"></button><label class="rate"><span></span><select><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></label></div><div class="steps"></div></div><div class="content"><div class="scene"></div><div class="caption"><p class="narration"></p><p class="formula"></p><p class="takeaway"></p></div></div><p class="status" role="status"></p></section>';
  this.#scene=document.createElement('lri-motion-scene');this.#scene.setAttribute('data-lesson-player','');this.#scene.setAttribute('fit','fit');this.#root.querySelector('.scene').append(this.#scene);
 }
 set lesson(data){this.pause();this.#data=data;this.#ui=data.ui;lessonArithmetic(data.method,data.values);this.#step=0;this.#elapsed=0;if(this.isConnected)this.#render();}
 get lesson(){return this.#data;}
 get currentTime(){return this.#data?this.#data.steps.slice(0,this.#step).reduce((s,r)=>s+r.duration_ms,0)+this.#elapsed:0;}
 get duration(){return this.#data?.steps.reduce((s,r)=>s+r.duration_ms,0)||0;}
 get playbackRate(){return this.#rate;}
 set playbackRate(v){const rate=Number(v);if(![.5,1,1.5,2].includes(rate))throw new RangeError('Unsupported lesson rate');this.#rate=rate;this.#root.querySelector('select').value=String(rate);this.#sync();}
 get reducedMotion(){return !!this.#motion?.matches;}
 connectedCallback(){
  if(Object.prototype.hasOwnProperty.call(this,'lesson')){const value=this.lesson;delete this.lesson;this.lesson=value;}
  this.#abort=new AbortController();this.#motion=matchMedia('(prefers-reduced-motion: reduce)');
  const on=(target,type,fn)=>target.addEventListener(type,fn,{signal:this.#abort.signal});
  on(this.#root,'click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step!==undefined){this.go(Number(b.dataset.step));this.#revealStage();return;}const action=b.dataset.action;if(action==='prev')this.go(this.#step-1);if(action==='next')this.go(this.#step+1);if(action==='play'){this.#playing?this.pause():this.play();this.#revealStage();}if(action==='restart')this.restart();if(['prev','next','restart'].includes(action))this.#revealStage();});
  on(this.#root.querySelector('select'),'change',e=>{this.playbackRate=e.target.value;});
  on(document,'visibilitychange',()=>{if(document.hidden)this.pause('hidden');});
  on(window,'hashchange',()=>this.pause('chapter'));
  on(this.#motion,'change',()=>{this.pause('reduced');this.#renderScene();});
  on(this.#scene,'scene-ready',()=>{this.#ready=true;this.#scene.seek(this.reducedMotion?this.#data?.steps[this.#step]?.duration_ms||0:this.#elapsed);});
  this.#intersection=new IntersectionObserver(entries=>{this.#visible=entries[0].isIntersecting;if(!this.#visible)this.pause('offscreen');});this.#intersection.observe(this);
  this.#resize=new ResizeObserver(entries=>{const narrow=entries[0].contentRect.width<560;if(narrow!==this.#narrow){this.#narrow=narrow;this.#renderScene();}});this.#resize.observe(this);
  this.#narrow=this.clientWidth<560;if(this.#data)this.#render();
 }
 disconnectedCallback(){this.pause();this.#pending++;this.#abort?.abort();this.#intersection?.disconnect();this.#resize?.disconnect();}
 play(){if(!this.#data||this.reducedMotion||document.hidden||!this.#visible)return;if(this.currentTime>=this.duration){this.#step=0;this.#elapsed=0;this.#render();}this.#playing=true;this.#reason='playing';this.#last=performance.now();this.#sync();cancelAnimationFrame(this.#raf);this.#raf=requestAnimationFrame(t=>this.#tick(t));}
 pause(reason='paused'){this.#playing=false;this.#reason=reason;cancelAnimationFrame(this.#raf);this.#scene?.pause?.();this.#sync();}
 restart(){this.pause();this.#step=0;this.#elapsed=0;this.#render();}
 go(n){if(!this.#data)return;this.pause();this.#step=Math.max(0,Math.min(this.#data.steps.length-1,n));this.#elapsed=0;this.#render();}
 seek(ms){if(!this.#data)return;this.pause();let t=Math.max(0,Math.min(this.duration,Number(ms)||0));let i=0;while(i<this.#data.steps.length-1&&t>=this.#data.steps[i].duration_ms){t-=this.#data.steps[i++].duration_ms;}this.#step=i;this.#elapsed=t;this.#render();}
 #tick(now){if(!this.#playing)return;this.#elapsed+=(now-this.#last)*this.#rate;this.#last=now;
  const current=this.#data.steps[this.#step];if(this.#elapsed>=current.duration_ms){if(this.#step===this.#data.steps.length-1){this.#elapsed=current.duration_ms;this.pause('complete');this.#scene.seek(this.#elapsed);return;}this.#elapsed=0;this.#step++;this.#render();}
  if(this.#ready)this.#scene.seek(this.#elapsed);this.#progress();this.#raf=requestAnimationFrame(t=>this.#tick(t));
 }
 #render(){if(!this.#data)return;const {steps,locale,ui,referenceNumbers}=this.#data,row=steps[this.#step],pick=k=>row[k+'_'+locale];this.#root.querySelector('.eyebrow').textContent=ui.lesson+' · '+(this.#step+1)+' / '+steps.length;this.#root.querySelector('h3').textContent=pick('title');this.#root.querySelector('.narration').textContent=pick('narration');
  const formula=this.#root.querySelector('.formula');formula.textContent=row.formula;formula.hidden=!row.formula;const takeaway=this.#root.querySelector('.takeaway');takeaway.textContent=pick('takeaway');const a=document.createElement('a');a.className='citation';a.textContent='['+referenceNumbers[row.source_url]+']';a.href='#foundation-ref-'+referenceNumbers[row.source_url];a.title=row.source_title+' · '+row.evidence_locator;a.setAttribute('aria-label',row.source_title+' · '+row.evidence_locator);a.addEventListener('click',e=>{e.preventDefault();location.hash=a.hash;});takeaway.append(a);
  const nav=this.#root.querySelector('.steps');nav.replaceChildren();steps.forEach((r,i)=>{const b=document.createElement('button');b.type='button';b.dataset.step=i;b.textContent=i+1;b.title=r['title_'+locale];b.setAttribute('aria-label',(i+1)+'. '+r['title_'+locale]);if(i===this.#step)b.setAttribute('aria-current','step');nav.append(b);});
  this.#scene.setAttribute('lang',locale);this.#scene.setAttribute('aria-label',pick('title'));this.#renderScene();this.#sync();
 }
 // Manual navigation starts at the new explanation, clear of the shared sticky header.
 #revealStage(){requestAnimationFrame(()=>{if(!this.isConnected)return;const header=this.#root.querySelector('header'),rect=header.getBoundingClientRect();if(rect.top<94||rect.top>104)header.scrollIntoView({block:'start',behavior:'instant'});});}
 async #renderScene(){if(!this.#data||!this.isConnected)return;this.#ready=false;const ticket=++this.#pending;await customElements.whenDefined('lri-motion-scene');if(ticket!==this.#pending)return;this.#scene.sceneMarkup=renderLessonSVG({...this.#data,step:this.#data.steps[this.#step],narrow:this.#narrow});}
 #progress(){const bar=this.#root.querySelector('.progress span');if(bar)bar.style.width=(this.duration?100*this.currentTime/this.duration:0)+'%';}
 #sync(){if(!this.#data||!this.#ui)return;const q=s=>this.#root.querySelector(s),u=this.#ui;q('[data-action=prev]').textContent=u.previous;q('[data-action=next]').textContent=u.next;q('[data-action=restart]').textContent=u.replay;q('[data-action=play]').textContent=this.#playing?u.pause:u.play;q('[data-action=play]').setAttribute('aria-pressed',String(this.#playing));q('[data-action=play]').disabled=this.reducedMotion;q('[data-action=prev]').disabled=this.#step===0;q('[data-action=next]').disabled=this.#step===this.#data.steps.length-1;q('.rate span').textContent=u.speed;q('select').setAttribute('aria-label',u.speed);q('select').disabled=this.reducedMotion;q('select').value=String(this.#rate);q('.status').textContent=this.reducedMotion?u.reduced:(u[this.#reason]||u.paused);this.#progress();this.dataset.lessonStep=String(this.#step);this.dataset.lessonState=this.#playing?'playing':'paused';this.dispatchEvent(new CustomEvent('lesson-state',{detail:{step:this.#step,playing:this.#playing,currentTime:this.currentTime}}));}
}
if(!customElements.get('lri-foundation-lesson'))customElements.define('lri-foundation-lesson',LriFoundationLesson);
